def _install_audit_protection() -> None:
    """Make audit_record append-only for every role, including the owner.

    TRUNCATE is blocked by a statement-level trigger. A superuser can still
    disable triggers (session_replication_role), which is why the application
    connects with a separate, non-superuser role.
    """
